∀ {Γ : Type u_1} {R : Type u_2} [inst : PartialOrder Γ] [inst_1 : Zero R] (coeff coeff_1 : Γ → R)
  (e_coeff : coeff = coeff_1) (isPWO_support' : (Function.support coeff).IsPWO),
  { coeff := coeff, isPWO_support' := isPWO_support' } = { coeff := coeff_1, isPWO_support' := ⋯ }

∀ {p : ℕ} [inst : Fact (Nat.Prime p)] {f : 𝕃_[p]} {T : ℕ+} {S : Set FormalizedSparse.Sparse.DigitSeries}
  {hS : ∀ d ∈ S, d.IsP p}
  {hf2 :
    FormalizedSparse.IsRepModZ (⇑(FormalizedSparse.Sparse.DigitSeries.norm p) '' S)
      {x | ∃ q ∈ f.support, -1 * ↑↑T * q = x}}
  {C n : ℕ+},
  FormalizedSparse.Sparse.IsCNSparse p C n S hS →
    FormalizedSparse.MainTheorem.FhatData✝ f T hf2 →
      ∀ {P : Polynomial ℚᵘⁿ_[p]}, (Polynomial.aeval f) P = 0 → P.natDegree = ↑n → P.coeff ↑n ≠ 0 → False

∀ {G : Type u_1} {α : Type u_2} [inst : TopologicalSpace G] [inst_1 : Sub G] [ContinuousSub G] {f g : α → G}
  {l : Filter α} {a b : G},
  Filter.Tendsto f l (nhds a) → Filter.Tendsto g l (nhds b) → Filter.Tendsto (fun x ↦ f x - g x) l (nhds (a - b))

∀ (p : ℕ) [inst : Fact (Nat.Prime p)] {x y : FormalizedSparse.LiftedPAdicHahnSeries p},
  x ∈ {x | FormalizedSparse.IsNullSeries x} →
    y ∈ {x | FormalizedSparse.IsNullSeries x} → x + y ∈ {x | FormalizedSparse.IsNullSeries x}

∀ {α : Type u_1} [inst : AddCommMonoid α] [inst_1 : PartialOrder α] [inst_2 : IsOrderedCancelAddMonoid α] {s t : Set α}
  {hs : s.IsPWO} {ht : t.IsPWO} {a : α} {x : α × α},
  x ∈ Finset.addAntidiagonal hs ht a ↔ x.1 ∈ s ∧ x.2 ∈ t ∧ x.1 + x.2 = a

∀ (p : ℕ) [inst : Fact (Nat.Prime p)],
  FormalizedSparse.NullSeriesIdeal p =
    { carrier := {x | FormalizedSparse.IsNullSeries x}, add_mem' := ⋯, zero_mem' := ⋯, smul_mem' := ⋯ }

∀ (p : ℕ) [inst : Fact (Nat.Prime p)] (c : FormalizedSparse.LiftedPAdicHahnSeries p)
  {x : FormalizedSparse.LiftedPAdicHahnSeries p},
  x ∈ {x | FormalizedSparse.IsNullSeries x} → c • x ∈ {x | FormalizedSparse.IsNullSeries x}

∀ {e : NNReal},
  (if hx : 0 = 0 then 0 else e ^ Multiplicative.toAdd (WithZero.unzero hx)) =
    if hx : 0 = 0 then 0 else e ^ Multiplicative.toAdd (WithZero.unzero hx)

∀ {α : Type u_2} {M : Type u_3} [inst : TopologicalSpace M] [inst_1 : Mul M] [ContinuousMul M] (b : M) {c : M}
  {f : α → M} {l : Filter α},
  Filter.Tendsto (fun k ↦ f k) l (nhds c) → Filter.Tendsto (fun k ↦ b * f k) l (nhds (b * c))

∀ (a : ℕ) (L : List ℕ),
  FormalizedSparse.Sparse.DigitSeries.ofCoeffs (a :: L) =
    { toFun := Function.update (⇑(FormalizedSparse.Sparse.DigitSeries.ofCoeffs L)) L.length.succPNat a, fin_supp := ⋯ }

∀ {ι : Type u_1} {M : Type u_3} {N : Type u_4} [inst : AddCommMonoid M] [inst_1 : AddCommMonoid N] {G : Type u_7}
  [inst_2 : FunLike G M N] [AddMonoidHomClass G M N] (g : G) (f : ι → M) (s : Finset ι),
  g (∑ x ∈ s, f x) = ∑ x ∈ s, g (f x)

∀ {p : ℕ} [inst : Fact (Nat.Prime p)] {S : Set FormalizedSparse.Sparse.DigitSeries} {hS : ∀ f ∈ S, f.IsP p} {c n : ℕ+}
  (hSparse : FormalizedSparse.Sparse.IsCNSparse p c n S hS) (d : ↑S),
  FormalizedSparse.Sparse.φ₀ hSparse d = Nat.card ↑(⋯.choose ⁻¹' {d})

∀ (p : ℕ) [inst : Fact (Nat.Prime p)],
  have hp1 := ⋯;
  StrictMono ⇑(WithZeroMulInt.toNNReal ⋯)

∀ {p : ℕ} [inst : Fact (Nat.Prime p)] (s : ℚ → 𝔽ᵃ_[p]) (hspwo : (Function.support s).IsPWO),
  FormalizedSparse.LiftedPAdicHahnSeries.from_coeff s hspwo =
    { coeff := fun n ↦ (WittVector.teichmuller p) (s n), isPWO_support' := ⋯ }

∀ {ι : Type u_1} {κ : Type u_2} {M : Type u_4} [inst : AddCommMonoid M] {s : Finset ι} {t : Finset κ}
  [inst_1 : DecidableEq κ] {g : ι → κ},
  (∀ i ∈ s, g i ∈ t) → ∀ (f : ι → M), ∑ j ∈ t, ∑ i ∈ s with g i = j, f i = ∑ i ∈ s, f i

∀ {toFun : ℕ+ → ℕ} {fin_supp : (Function.support toFun).Finite} {toFun_1 : ℕ+ → ℕ}
  {fin_supp_1 : (Function.support toFun_1).Finite},
  { toFun := toFun, fin_supp := fin_supp } = { toFun := toFun_1, fin_supp := fin_supp_1 } → toFun = toFun_1

∀ {α : Type u_1} [inst : AddCommMonoid α] [inst_1 : PartialOrder α] [inst_2 : IsOrderedCancelAddMonoid α] {s t : Set α}
  {hs : s.IsPWO} {ht : t.IsPWO} {a : α} {x : α × α},
  (x ∈ Finset.addAntidiagonal hs ht a) = (x.1 ∈ s ∧ x.2 ∈ t ∧ x.1 + x.2 = a)

∀ (p : ℕ) [inst : Fact (Nat.Prime p)],
  have hp1 := ⋯;
  StrictMono ⇑(WithZeroMulInt.toNNReal ⋯)

∀ {M : Type u_1} [inst : TopologicalSpace M] [inst_1 : Add M] [ContinuousAdd M] {α : Type u_2} {f g : α → M}
  {x : Filter α} {a b : M},
  Filter.Tendsto f x (nhds a) → Filter.Tendsto g x (nhds b) → Filter.Tendsto (fun x ↦ f x + g x) x (nhds (a + b))

∀ (x : List ℕ),
  FormalizedSparse.Sparse.DigitSeries.ofCoeffs x =
    match x with
    | [] => { toFun := 0, fin_supp := FormalizedSparse.Sparse.DigitSeries.ofCoeffs._proof_1 }
    | a :: L =>
      let f := FormalizedSparse.Sparse.DigitSeries.ofCoeffs L;
      { toFun := Function.update (⇑f) L.length.succPNat a, fin_supp := ⋯ }

∀ (p : ℕ) [inst : Fact (Nat.Prime p)] (T : ℕ) [inst_1 : NeZero T]
  (c : FormalizedSparse.TScaled.TLiftedPAdicHahnSeries p T) {x : FormalizedSparse.TScaled.TLiftedPAdicHahnSeries p T},
  x ∈ {x | FormalizedSparse.TScaled.IsTNullSeries p T x} → c • x ∈ {x | FormalizedSparse.TScaled.IsTNullSeries p T x}
